/* =========================================================
   Utilities
========================================================= */

function normalize(s) {
  return String(s ?? "")
    .toLowerCase()
    .trim()
    .replace(/[_\-]+/g, " ")
    .replace(/[().,:;]/g, "")
    .replace(/\s+/g, " ");
}

function guessColumn(headers, aliases) {
  const norm = headers.map((h) => ({ orig: h, n: normalize(h) }));
  for (const a of aliases) {
    const na = normalize(a);
    const hit = norm.find((h) => h.n === na);
    if (hit) return hit.orig;
  }
  for (const a of aliases) {
    const na = normalize(a);
    const hit = norm.find((h) => h.n.includes(na) || na.includes(h.n));
    if (hit) return hit.orig;
  }
  return null;
}

function normalizeDomain(d) {
  if (!d) return "";
  let s = String(d).trim().toLowerCase();
  s = s.replace(/^https?:\/\//, "");
  s = s.replace(/^www\./, "");
  s = s.replace(/\/.*$/, "");
  return s;
}

function normalizePageUrl(u) {
  if (!u) return "";
  let s = String(u).trim().toLowerCase();
  s = s.replace(/^https?:\/\/(www\.)?/, "");  // прибираємо протокол і www.
  if (s.length > 1 && s.endsWith("/")) s = s.slice(0, -1);  // прибираємо кінцевий слеш
  return s;
}

// For turning a stored URL/bare-domain string into something usable as an <a href>.
// Donor URLs and similar fields are often stored without a protocol (e.g. "example.com").
function asClickableUrl(u) {
  if (!u) return null;
  const s = String(u).trim();
  if (!s) return null;
  return /^https?:\/\//i.test(s) ? s : `https://${s}`;
}

function parseFlexibleDate(raw) {
  if (raw == null || raw === "") return null;
  if (raw instanceof Date) return isNaN(raw.getTime()) ? null : raw;
  const s = String(raw).trim();
  // Excel serial number (наприклад, 45175)
  const n = parseFloat(s);
  if (!isNaN(n) && n > 1000 && n < 2958466 && /^\d+(\.\d+)?$/.test(s)) {
    // Excel epoch: Dec 30, 1899; 25569 = days between Excel epoch and Unix epoch
    const jsDate = new Date(Math.round((n - 25569) * 86400000));
    if (!isNaN(jsDate.getTime())) return jsDate;
  }
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function parseNum(v) {
  if (v == null || v === "") return null;
  const s = String(v).replace(/%/g, "").replace(/\s/g, "").replace(",", ".");
  const n = parseFloat(s);
  return isNaN(n) ? null : n;
}

function isDateLikeHeader(h) {
  const s = String(h ?? "").trim();
  return (
    /^\d{4}-\d{1,2}-\d{1,2}$/.test(s) || /^\d{1,2}[.\/]\d{1,2}[.\/]\d{2,4}$/.test(s)
  );
}

function dayKey(date) {
  // Повертає timestamp початку дня UTC+3
  const k = _toKyiv(date);
  return Date.UTC(k.getUTCFullYear(), k.getUTCMonth(), k.getUTCDate());
}

function daysInMonth(date) {
  const k = _toKyiv(date);
  return new Date(Date.UTC(k.getUTCFullYear(), k.getUTCMonth() + 1, 0)).getUTCDate();
}

// Monday–Sunday range UTC+3 (початок тижня — понеділок)
function currentWeekRange(now = new Date()) {
  const k = _toKyiv(now);
  const day = k.getUTCDay(); // 0=Sun..6=Sat
  const diffToMonday = day === 0 ? -6 : 1 - day;
  const monday = Date.UTC(k.getUTCFullYear(), k.getUTCMonth(), k.getUTCDate() + diffToMonday);
  const sunday = monday + 7 * 24 * 60 * 60 * 1000 - 1; // кінець неділі UTC+3
  return [monday, sunday];
}

function isArticleDone(r) {
  const s = String(r.articleDone || "").trim().toLowerCase();
  return s === STATUSES.article.DONE_AND_INDEXED
      || s === STATUSES.article.DONE_NOT_INDEXED
      || s === STATUSES.article.DONE_AND_DELETED
      || s === STATUSES.article.DONE_AND_MODERATING;
}
function isArticleNotPosted(r) {
  const s = String(r.articleDone || "").trim().toLowerCase();
  return s === STATUSES.article.IN_PROGRESS || s === STATUSES.article.PREPARED;
}
function isContentUrgent(r, refDate = new Date()) {
  // Термінова: статус "не запощено" і planDate завтра або вже минула
  if (!isArticleNotPosted(r) || !r.planDate) return false;
  const todayTs    = dayKey(refDate);
  const tomorrowTs = todayTs + 24 * 60 * 60 * 1000;
  return dayKey(r.planDate) <= tomorrowTs;
}
function isContentOverdue(r, refDate = new Date()) {
  // Прострочена: статус "не запощено" і planDate вже минула
  if (!isArticleNotPosted(r) || !r.planDate) return false;
  return dayKey(r.planDate) < dayKey(refDate);
}

function isLinkDone(r) {
  const s = String(r.linkDone || "").trim().toLowerCase();
  return s === STATUSES.link.DONE_AND_INDEXED
      || s === STATUSES.link.DONE_NOT_INDEXED
      || s === STATUSES.link.DONE_AND_MODERATING
      || s === STATUSES.link.DONE_AND_DELETED
      || s === STATUSES.link.CANT_BE_INDEXED;
}
function isTechTaskActive(t) {
  const s = String(t.status || "").trim().toLowerCase();
  return s === STATUSES.techTask.IN_PROGRESS || s === STATUSES.techTask.IN_MODERATING;
}
function isTechTaskOverdue(t, refDate = new Date()) {
  if (!isTechTaskActive(t) || !t.planingTaskDate) return false;
  return dayKey(t.planingTaskDate) < dayKey(refDate);
}
function isTechTaskUrgent(t, refDate = new Date()) {
  if (!isTechTaskActive(t) || !t.planingTaskDate) return false;
  const tomorrowTs = dayKey(refDate) + 24 * 60 * 60 * 1000;
  return dayKey(t.planingTaskDate) <= tomorrowTs && !isTechTaskOverdue(t, refDate);
}

function isLinkNotPlaced(r) {
  return String(r.linkDone || "").trim().toLowerCase() === STATUSES.link.IN_PROGRESS;
}
function isLinkUrgent(r, refDate = new Date()) {
  if (!isLinkNotPlaced(r) || !r.planDate) return false;
  const todayTs    = dayKey(refDate);
  const tomorrowTs = todayTs + 24 * 60 * 60 * 1000;
  return dayKey(r.planDate) <= tomorrowTs;
}
function isLinkOverdue(r, refDate = new Date()) {
  if (!isLinkNotPlaced(r) || !r.planDate) return false;
  return dayKey(r.planDate) < dayKey(refDate);
}

// Хелпер: переводить будь-який timestamp у UTC+3 об'єкт
function _toKyiv(ts) {
  const d = new Date(ts instanceof Date ? ts : typeof ts === "number" ? ts : new Date(ts));
  // UTC+3: зсув 3*60 хвилин
  return new Date(d.getTime() + 3 * 60 * 60 * 1000);
}

// Єдиний формат дат: ДД.ММ.РРРР (UTC+3, рік обов'язковий, без суфіксів)
function _fmtDate(ts) {
  if (!ts && ts !== 0) return "—";
  const k = _toKyiv(ts);
  return `${String(k.getUTCDate()).padStart(2,"0")}.${String(k.getUTCMonth()+1).padStart(2,"0")}.${k.getUTCFullYear()}`;
}
function formatDateShort(ts)   { return _fmtDate(ts); }
function formatDateNumeric(ts) { return _fmtDate(ts); }
function formatDateFull(ts)    { return _fmtDate(ts); }

// Форматування з часом (для задач та логів) — UTC+3
function formatDateTimeKyiv(ts) {
  if (!ts) return "—";
  const k = _toKyiv(ts);
  const d = `${String(k.getUTCDate()).padStart(2,"0")}.${String(k.getUTCMonth()+1).padStart(2,"0")}.${k.getUTCFullYear()}`;
  const t = `${String(k.getUTCHours()).padStart(2,"0")}:${String(k.getUTCMinutes()).padStart(2,"0")}`;
  return `${d}, ${t}`;
}

// Поточна дата UTC+3 (початок дня)
function todayKyiv() {
  const k = _toKyiv(Date.now());
  return new Date(Date.UTC(k.getUTCFullYear(), k.getUTCMonth(), k.getUTCDate()));
}
// Builds the small caption under a StatCard: for a "current value" card, when the data point
// is from; for a "change" card, what it went from → to and over what window, so the number
// doesn't need to be taken on faith.
function asOfHint(date) {
  return date != null ? `станом на ${formatDateShort(date)}` : null;
}
function deltaHint(fromVal, toVal, fromDate, toDate, decimals = 1) {
  if (fromVal == null || toVal == null) return null;
  const fmt = (v) => v.toFixed(decimals);
  const valuePart = `${fmt(fromVal)} → ${fmt(toVal)}`;
  const datePart = fromDate != null && toDate != null ? ` (${formatDateShort(fromDate)}–${formatDateShort(toDate)})` : "";
  return valuePart + datePart;
}

// Domain importance tiers, based on the sum of Calculate Level over the last 12 months (not
// all-time max — a rolling window reflects current relevance, not a historical peak). Fixed
// value thresholds (not relative percentiles) so a domain's tier doesn't shift just because
// other domains were added or removed in a later upload. Calibrated against a real
// ~420-domain distribution so Level 1 stays under 10 domains and each lower tier holds
// progressively more.
const DOMAIN_IMPORTANCE_TIERS = [
  { level: 1, min: 2500, label: "Level 1" },
  { level: 2, min: 200, label: "Level 2" },
  { level: 3, min: 5, label: "Level 3" },
  { level: 4, min: -Infinity, label: "Level 4" },
];
function levelBadgeColor(level) {
  return level === 1 ? "text-emerald-700 bg-emerald-50"
       : level === 2 ? "text-amber-600 bg-amber-50"
       : level === 3 ? "text-blue-700 bg-blue-50"
       : "text-slate-600 bg-slate-100";
}
function domainImportanceLevel(sumLastYearVal) {
  if (sumLastYearVal == null) return null;
  return DOMAIN_IMPORTANCE_TIERS.find((t) => sumLastYearVal >= t.min) || null;
}
// Sum of a Calculate Level series' values over the rolling last 12 months from refDate.
function sumLastYear(series, refDate = new Date()) {
  if (!series || !series.length) return 0;
  const cutoff = new Date(refDate.getFullYear() - 1, refDate.getMonth(), refDate.getDate());
  return series.reduce((sum, s) => (s.date >= cutoff ? sum + (s.calc || 0) : sum), 0);
}

let _uidN = 0;
function uid() {
  _uidN += 1;
  return `r${Date.now()}_${_uidN}`;
}

// date → "YYYY-MM-DD" string for <input type="date"> value attribute.
function toDateInputStr(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

