// Колір прогрес-бару залежно від відсотка виконання
function pctBar(p) {
  if (p >= 80) return "bg-emerald-500";
  if (p >= 50) return "bg-amber-400";
  if (p > 0)   return "bg-amber-300";
  return "bg-slate-200";
}

// Палітра кольорів для категорій/серій на графіках
const CATEGORY_PALETTE       = ["#4F46E5", "#0EA5E9", "#059669", "#CA8A04", "#DB2777", "#7C3AED", "#DC2626", "#0F766E"];
const OTHER_CATEGORY_COLOR   = "#94A3B8";
const PLANNED_CATEGORY_COLOR = "#334155";

// Range of a numeric array: [min, max] or null when empty.
function computeBounds(arr) {
  const clean = arr.filter((v) => v != null && !isNaN(v));
  if (!clean.length) return null;
  return [Math.min(...clean), Math.max(...clean)];
}
// Keep only events whose .date falls within [min, max].
function clipToRange(events, bounds) {
  if (!bounds) return [];
  const [min, max] = bounds;
  return events.filter((e) => e.date >= min && e.date <= max);
}

