const top100Storage   = createStorageSlice("signal-seo-top100-v1");
const donorStorage    = createStorageSlice("signal-seo-donors-v1");
const ourDomStorage   = createStorageSlice("signal-seo-our-domains-v1");
const techWorkStorage = createStorageSlice("signal-seo-techwork-v1");
const tasksStorage    = createStorageSlice("signal-seo-tasks-v1");

