// Historical Link Type / Anchor Type values in real exports are messy (typos, casing,
// legacy categories). Known variants are folded into the canonical taxonomy; anything
// unrecognized is kept as-is rather than force-fit, so legacy data isn't misclassified.
function normalizeLinkType(raw) {
  const s = String(raw ?? "").trim();
  if (!s) return "";
  const n = s.toLowerCase();
  if (["business listing", "bl", "business listings"].includes(n)) return "Business Listings";
  if (["profile"].includes(n)) return "Profile";
  if (n === "pbn ai article") return "PBN AI Article";
  if (n.startsWith("pbn link insertion")) return "PBN Link Insertion";
  if (n === "pbn-h" || ((n.startsWith("pbn") || n.startsWith("pbh")) && n.includes("home"))) return "PBN Homepage";
  if (n === "img" || n.startsWith("img ")) return "IMG";
  return s;
}
function normalizeAnchorType(raw) {
  const s = String(raw ?? "").trim();
  if (!s) return "";
  const n = s.toLowerCase().replace(/\s+/g, " ");
  if (n === "url") return "URL";
  if (n === "exact match") return "Exact Match";
  if (n === "partial match") return "Partial Match";
  if (n === "generic") return "Generic";
  return s;
}

