/* =========================================================
   App-wide constants & data transforms
   Pure functions / static config that don't depend on React
   state — hoisted out of App so they're defined once.
========================================================= */

// UI list caps — keep rendered checkboxes under a safe DOM count.
const CALC_PAGE_LIST_CAP       = 50;
const KEYWORD_LIST_CAP         = 50;
const TOP100_KEYWORD_LIST_CAP  = 50;

// Keyword metric display config (labels, chart axis, dash style).
const KEYWORD_METRIC_LABELS = { position: "Позиція", clicks: "Кліки", impressions: "Покази", ctr: "CTR" };
const KEYWORD_METRIC_AXIS   = { position: "left", clicks: "right", impressions: "right", ctr: "ctr" };
const KEYWORD_METRIC_DASH   = { position: undefined, clicks: "5 3", impressions: "1 3", ctr: "7 3 2 3" };

// A row with no real publication date but a planned one is treated as "planned" — it still
// gets plotted on the timeline, just tagged differently, until an actual date replaces it.
function reconcileContentDates(row) {
  const isPlanned = !row.postDate && !!row.planDate;
  return { ...row, status: isPlanned ? "planned" : "published", postDate: row.postDate || row.planDate };
}
function reconcileLinkDates(row) {
  const isPlanned = !row.linkDate && !!row.planDate;
  return { ...row, status: isPlanned ? "planned" : "created", linkDate: row.linkDate || row.planDate };
}

/* =========================================================
   Rows table (list of manually / file entered records, deletable)
========================================================= */

function RowsTable({ rows, cols, dateKey, onDelete }) {
  const CAP = 300;
  const sorted = useMemo(
    () =>
      [...rows].sort((a, b) => {
        const ta = a[dateKey] ? new Date(a[dateKey]).getTime() : 0;
        const tb = b[dateKey] ? new Date(b[dateKey]).getTime() : 0;
        return tb - ta;
      }),
    [rows, dateKey]
  );
  const shown = sorted.slice(0, CAP);
  return (
    <div>
      <div className="mt-3 max-h-64 overflow-auto rounded-md border border-slate-200">
        <table className="w-full text-xs">
          <thead className="sticky top-0 bg-slate-50 text-slate-500">
            <tr>
              {cols.map((c) => (
                <th key={c.key} className="px-2 py-1.5 text-left font-medium">{c.label}</th>
              ))}
              <th className="w-6" />
            </tr>
          </thead>
          <tbody>
            {shown.map((r) => (
              <tr key={r.id} className="border-t border-slate-100 hover:bg-slate-50">
                {cols.map((c) => (
                  <td key={c.key} className="whitespace-nowrap px-2 py-1.5 text-slate-700">
                    {c.date ? (r[c.key] ? formatDateFull(r[c.key]) : "—") : c.transform ? c.transform(r[c.key], r) : r[c.key] || "—"}
                  </td>
                ))}
                <td className="px-1">
                  <button onClick={() => onDelete(r.id)} className="text-slate-300 hover:text-red-600" title="Видалити">
                    <X className="h-3.5 w-3.5" />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {sorted.length > CAP && (
        <p className="mt-1 text-[11px] text-slate-400">Показано {CAP} найновіших з {sorted.length} рядків.</p>
      )}
    </div>
  );
}

/* =========================================================
   Upload panels — file upload, snapshots, Calculate Level, Top100
========================================================= */

/* =========================================================
   Upload panel — content plan / linkbuilding
   Supports: file import (CSV/XLSX) with column mapping, OR manual entry
========================================================= */

function UploadPanel({ title, icon: Icon, accent, fields, rows, onAdd, onClear, onDeleteRow, tableCols, dateKey, note }) {
  const [showRows, setShowRows] = useState(false);
  const [parsed, setParsed] = useState(null);
  const [mapping, setMapping] = useState({});
  const [status, setStatus] = useState(null);
  const inputRef = useRef(null);

  async function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    setStatus(null);
    try {
      const { headers, rows: rawRows } = await parseFile(file);
      const guess = {};
      fields.forEach((f) => {
        guess[f.key] = guessColumn(headers, f.aliases) || "";
      });
      setParsed({ headers, rawRows, fileName: file.name });
      setMapping(guess);
    } catch (err) {
      setStatus({ type: "error", text: "Не вдалося прочитати файл. Перевірте формат (CSV/XLSX)." });
    }
    if (inputRef.current) inputRef.current.value = "";
  }

  function commitFile() {
    if (!parsed) return;
    const missing = fields.filter((f) => f.required && !mapping[f.key]);
    if (missing.length) {
      setStatus({ type: "error", text: `Оберіть колонку для: ${missing.map((f) => f.label).join(", ")}` });
      return;
    }
    const newRows = [];
    parsed.rawRows.forEach((r) => {
      const obj = { id: uid() };
      let ok = true;
      fields.forEach((f) => {
        const col = mapping[f.key];
        let val = col ? r[col] : "";
        if (f.key === "domain") val = normalizeDomain(val);
        if (f.date) {
          val = parseFlexibleDate(val);
          if (f.required && !val) ok = false;
        } else if (f.urlNorm) {
          val = normalizePageUrl(val);
          if (f.required && !val) ok = false;
        } else if (f.normalizeType === "linkType") {
          val = normalizeLinkType(val);
          if (f.required && !val) ok = false;
        } else if (f.normalizeType === "anchorType") {
          val = normalizeAnchorType(val);
          if (f.required && !val) ok = false;
        } else {
          val = val == null ? "" : String(val).trim();
          if (f.required && !val) ok = false;
        }
        obj[f.key] = val;
      });
      if (ok) newRows.push(obj);
    });
    onAdd(newRows);
    setStatus({ type: "ok", text: `Додано ${newRows.length} рядків (з ${parsed.rawRows.length}).` });
    setParsed(null);
    setMapping({});
  }

  return (
    <div className="rounded-lg border border-slate-200 bg-white p-5">
      <div className="mb-1 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h3 className="text-xs font-semibold uppercase tracking-wide text-slate-500">{title}</h3>
        </div>
        <div className="flex items-center gap-2">
          <span className="font-mono text-xs text-slate-500">{rows.length} рядків</span>
          {rows.length > 0 && (
            <button onClick={onClear} className="text-slate-400 transition-colors hover:text-red-600" title="Очистити все">
              <Trash2 className="h-4 w-4" />
            </button>
          )}
        </div>
      </div>

      {note && <p className="mt-1 text-xs text-slate-300 leading-relaxed">💡 {note}</p>}

      {status && (
        <p className={`mt-1 text-xs ${status.type === "error" ? "text-red-600" : "text-emerald-600"}`}>{status.text}</p>
      )}

      {!parsed && (
        <div className="mt-3">
          <label className="flex cursor-pointer items-center justify-center gap-2 rounded-md border border-dashed border-slate-300 py-6 text-sm text-slate-500 transition-colors hover:border-slate-400 hover:bg-slate-50">
            <Upload className="h-4 w-4" />
            Оберіть CSV або XLSX файл
            <input ref={inputRef} type="file" accept=".csv,.tsv,.txt,.xlsx,.xls" className="hidden" onChange={handleFile} />
          </label>
        </div>
      )}

      {parsed && (
        <div className="mt-3 space-y-3">
          <p className="truncate font-mono text-xs text-slate-500">{parsed.fileName} · {parsed.rawRows.length} рядків знайдено</p>
          <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
            {fields.map((f) => (
              <div key={f.key} className="flex flex-col gap-1">
                <label className="text-xs text-slate-500">
                  {f.label}
                  {f.required && <span className="text-red-500"> *</span>}
                </label>
                <select
                  value={mapping[f.key] || ""}
                  onChange={(e) => setMapping((m) => ({ ...m, [f.key]: e.target.value }))}
                  className="rounded-md border border-slate-300 bg-white px-2 py-1.5 text-sm text-slate-800"
                >
                  <option value="">— не використовувати —</option>
                  {parsed.headers.map((h) => (
                    <option key={h} value={h}>{h}</option>
                  ))}
                </select>
              </div>
            ))}
          </div>
          <div className="flex items-center gap-2 pt-1">
            <button onClick={commitFile} className={`rounded-md px-3 py-1.5 text-sm font-medium text-white transition-opacity hover:opacity-90 ${accent.solid}`}>
              Додати дані
            </button>
            <button
              onClick={() => {
                setParsed(null);
                setMapping({});
              }}
              className="rounded-md px-3 py-1.5 text-sm text-slate-500 hover:bg-slate-100"
            >
              Скасувати
            </button>
          </div>
        </div>
      )}

      {rows.length > 0 && (
        <div className="mt-4 border-t border-slate-100 pt-3">
          <button onClick={() => setShowRows((s) => !s)} className="text-xs font-medium text-slate-500 hover:text-slate-700">
            {showRows ? "Сховати записи" : `Показати записи (${rows.length})`}
          </button>
          {showRows && <RowsTable rows={rows} cols={tableCols} dateKey={dateKey} onDelete={onDeleteRow} />}
        </div>
      )}
    </div>
  );
}

/* =========================================================
   Snapshot upload panel — GSC / SE Ranking top100 (file only: xlsx/csv, manual domain + date)
========================================================= */

function SnapshotUploadPanel({ title, icon: Icon, accent, fields, mode, rows, knownDomains, onAdd, onClear, dateRangeMode, note }) {
  const [parsed, setParsed] = useState(null);
  const [mapping, setMapping] = useState({});
  const [domainInput, setDomainInput] = useState("");
  const [dateInput, setDateInput] = useState("");
  const [dateFromInput, setDateFromInput] = useState("");
  const [dateToInput, setDateToInput] = useState("");
  const [status, setStatus] = useState(null);
  const inputRef = useRef(null);
  const listId = useId();

  async function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    setStatus(null);
    try {
      const { headers, rows: rawRows, sheetName } = await parseFile(file);
      const melt = mode === "top100" ? meltWideDates(headers, rawRows) : null;
      let effHeaders = headers;
      let effRows = rawRows;
      let isWide = false;
      if (melt) {
        effHeaders = [...melt.idHeaders, "__value"];
        effRows = melt.meltedRows;
        isWide = true;
      }
      const guess = {};
      fields.forEach((f) => {
        guess[f.key] = guessColumn(effHeaders, f.aliases) || (isWide && f.key === "position" ? "__value" : "");
      });
      const domainGuessCol = guessColumn(effHeaders, ["domain", "сайт", "site", "домен", "project", "проект"]);
      setParsed({ headers: effHeaders, rawRows: effRows, isWide, fileName: file.name, domainGuessCol });
      setMapping(guess);
      setDomainInput(domainGuessCol ? "" : guessDomainFromSheetName(sheetName));
      setDateInput("");
      setDateFromInput("");
      setDateToInput("");
    } catch (err) {
      setStatus({ type: "error", text: "Не вдалося прочитати файл. Перевірте формат (CSV/XLSX)." });
    }
    if (inputRef.current) inputRef.current.value = "";
  }

  const hasDateField = fields.some((f) => f.key === "date");
  const perRowDate = hasDateField && !!mapping.date;

  function commit() {
    if (!parsed) return;
    const missing = fields.filter((f) => f.required && !mapping[f.key]);
    if (missing.length) {
      setStatus({ type: "error", text: `Оберіть колонку для: ${missing.map((f) => f.label).join(", ")}` });
      return;
    }
    const needManualDate = !parsed.isWide && !perRowDate;
    if (needManualDate && dateRangeMode) {
      if (!dateFromInput || !dateToInput) {
        setStatus({ type: "error", text: "Вкажіть період (з і по) для цього завантаження." });
        return;
      }
      if (dateFromInput > dateToInput) {
        setStatus({ type: "error", text: "Дата «з» не може бути пізніше дати «по»." });
        return;
      }
    } else if (needManualDate && !dateInput) {
      setStatus({ type: "error", text: "Вкажіть дату зрізу для цього завантаження." });
      return;
    }
    const needManualDomain = !parsed.domainGuessCol;
    if (needManualDomain && !domainInput.trim()) {
      setStatus({ type: "error", text: "Вкажіть домен для цього завантаження." });
      return;
    }
    const newRows = [];
    parsed.rawRows.forEach((r) => {
      const obj = { id: uid() };
      obj.domain = normalizeDomain(parsed.domainGuessCol ? r[parsed.domainGuessCol] : domainInput);
      if (parsed.isWide) {
        obj.date = parseFlexibleDate(r.__date);
      } else if (perRowDate) {
        obj.date = parseFlexibleDate(r[mapping.date]);
      } else if (dateRangeMode) {
        obj.date = parseFlexibleDate(dateToInput);
        obj.periodFrom = parseFlexibleDate(dateFromInput);
      } else {
        obj.date = parseFlexibleDate(dateInput);
      }
      let ok = !!obj.domain && !!obj.date;
      fields.forEach((f) => {
        if (f.key === "date") return; // already handled above
        const col = mapping[f.key];
        let val = col ? r[col] : "";
        if (f.num) val = parseNum(val);
        else if (f.urlNorm) val = normalizePageUrl(val);
        else val = val == null ? "" : String(val).trim();
        if (f.required && (val === "" || val == null)) ok = false;
        obj[f.key] = val;
      });
      if (ok) newRows.push(obj);
    });
    onAdd(newRows);
    setStatus({ type: "ok", text: `Додано ${newRows.length} рядків (з ${parsed.rawRows.length}).` });
    setParsed(null);
    setMapping({});
    setDomainInput("");
    setDateInput("");
    setDateFromInput("");
    setDateToInput("");
  }

  return (
    <div className="rounded-lg border border-slate-200 bg-white p-5">
      <div className="mb-1 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h3 className="text-xs font-semibold uppercase tracking-wide text-slate-500">{title}</h3>
        </div>
        <div className="flex items-center gap-2">
          <span className="font-mono text-xs text-slate-500">{rows.length} рядків</span>
          {rows.length > 0 && (
            <button onClick={onClear} className="text-slate-400 transition-colors hover:text-red-600" title="Очистити">
              <Trash2 className="h-4 w-4" />
            </button>
          )}
        </div>
      </div>

      {note && <p className="mt-1 text-xs text-slate-300 leading-relaxed">💡 {note}</p>}

      {!parsed && (
        <label className="mt-3 flex cursor-pointer items-center justify-center gap-2 rounded-md border border-dashed border-slate-300 py-6 text-sm text-slate-500 transition-colors hover:border-slate-400 hover:bg-slate-50">
          <Upload className="h-4 w-4" />
          Завантажити зріз (XLSX / CSV)
          <input ref={inputRef} type="file" accept=".csv,.tsv,.txt,.xlsx,.xls" className="hidden" onChange={handleFile} />
        </label>
      )}

      {parsed && (
        <div className="mt-3 space-y-3">
          <p className="truncate font-mono text-xs text-slate-500">{parsed.fileName} · {parsed.rawRows.length} рядків знайдено</p>

          {parsed.isWide && (
            <p className="rounded-md bg-teal-50 px-2 py-1.5 text-xs text-teal-700">
              Виявлено декілька дат-колонок — історію позицій розгорнуто автоматично по датах.
            </p>
          )}

          <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
            {!parsed.domainGuessCol && (
              <div className="flex flex-col gap-1">
                <label className="text-xs text-slate-500">
                  Домен для цього файлу<span className="text-red-500"> *</span>
                </label>
                <input
                  list={listId}
                  value={domainInput}
                  onChange={(e) => setDomainInput(e.target.value)}
                  placeholder="example.com"
                  className="rounded-md border border-slate-300 px-2 py-1.5 text-sm font-mono"
                />
                <datalist id={listId}>
                  {knownDomains.map((d) => (
                    <option key={d} value={d} />
                  ))}
                </datalist>
              </div>
            )}
            {parsed.domainGuessCol && (
              <p className="text-xs text-slate-400 sm:col-span-2">Домен визначено з колонки «{parsed.domainGuessCol}».</p>
            )}

            {!parsed.isWide && perRowDate && (
              <p className="rounded-md bg-teal-50 px-2 py-1.5 text-xs text-teal-700 sm:col-span-2">
                Дата береться з колонки «{mapping.date}» окремо для кожного рядка — реальна щоденна динаміка, без ручного вводу періоду.
              </p>
            )}

            {!parsed.isWide && !perRowDate && dateRangeMode && (
              <>
                <div className="flex flex-col gap-1">
                  <label className="text-xs text-slate-500">
                    Період з<span className="text-red-500"> *</span>
                  </label>
                  <input
                    type="date"
                    value={dateFromInput}
                    max={dateToInput || undefined}
                    onChange={(e) => setDateFromInput(e.target.value)}
                    className="rounded-md border border-slate-300 px-2 py-1.5 text-sm font-mono"
                  />
                </div>
                <div className="flex flex-col gap-1">
                  <label className="text-xs text-slate-500">
                    по<span className="text-red-500"> *</span>
                  </label>
                  <input
                    type="date"
                    value={dateToInput}
                    min={dateFromInput || undefined}
                    onChange={(e) => setDateToInput(e.target.value)}
                    className="rounded-md border border-slate-300 px-2 py-1.5 text-sm font-mono"
                  />
                </div>
              </>
            )}

            {!parsed.isWide && !perRowDate && !dateRangeMode && (
              <div className="flex flex-col gap-1">
                <label className="text-xs text-slate-500">
                  Дата зрізу<span className="text-red-500"> *</span>
                </label>
                <input
                  type="date"
                  value={dateInput}
                  onChange={(e) => setDateInput(e.target.value)}
                  className="rounded-md border border-slate-300 px-2 py-1.5 text-sm font-mono"
                />
              </div>
            )}

            {fields.map((f) => (
              <div key={f.key} className="flex flex-col gap-1">
                <label className="text-xs text-slate-500">
                  {f.label}
                  {f.required && <span className="text-red-500"> *</span>}
                </label>
                <select
                  value={mapping[f.key] || ""}
                  onChange={(e) => setMapping((m) => ({ ...m, [f.key]: e.target.value }))}
                  className="rounded-md border border-slate-300 bg-white px-2 py-1.5 text-sm text-slate-800"
                >
                  <option value="">— не використовувати —</option>
                  {parsed.headers.map((h) => (
                    <option key={h} value={h}>{h === "__value" ? "(значення з дати-колонки)" : h}</option>
                  ))}
                </select>
              </div>
            ))}
          </div>

          <div className="flex items-center gap-2 pt-1">
            <button onClick={commit} className={`rounded-md px-3 py-1.5 text-sm font-medium text-white transition-opacity hover:opacity-90 ${accent.solid}`}>
              Додати дані
            </button>
            <button
              onClick={() => {
                setParsed(null);
                setMapping({});
              }}
              className="rounded-md px-3 py-1.5 text-sm text-slate-500 hover:bg-slate-100"
            >
              Скасувати
            </button>
          </div>
        </div>
      )}

      {status && (
        <p className={`mt-2 text-xs ${status.type === "error" ? "text-red-600" : "text-emerald-600"}`}>{status.text}</p>
      )}
    </div>
  );
}

/* =========================================================
   Calculate Level panel — dedicated parser for the fixed "total"/"domains" workbook
   (no column mapping, no manual entry: the layout is a known, fixed export format)
========================================================= */

function CalculateLevelPanel({ pages, domainsAgg, onLoad, onClear, saveWarning }) {
  const [status, setStatus] = useState(null);
  const [loading, setLoading] = useState(false);
  const [showRows, setShowRows] = useState(false);
  const inputRef = useRef(null);

  async function handleFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    setLoading(true);
    setStatus(null);
    try {
      const result = await parseCalculateLevelWorkbook(file);
      if (!result.pages.length && !result.domainsAgg.length) {
        setStatus({ type: "error", text: "Не знайдено жодного розпізнаного рядка. Перевірте листи «total» / «domains»." });
      } else {
        onLoad(result);
        const warn = result.unparsedPeriods.length
          ? ` Не розпізнано ${result.unparsedPeriods.length} колонок-періодів: ${result.unparsedPeriods.slice(0, 5).join(", ")}${result.unparsedPeriods.length > 5 ? "…" : ""}`
          : "";
        setStatus({ type: "ok", text: `Завантажено: ${result.pages.length} сторінок, ${result.domainsAgg.length} доменів.${warn}` });
      }
    } catch (err) {
      setStatus({ type: "error", text: err.message || "Не вдалося розпізнати файл." });
    } finally {
      setLoading(false);
      if (inputRef.current) inputRef.current.value = "";
    }
  }

  const topPages = useMemo(() => {
    return [...pages]
      .map((p) => ({ ...p, latest: p.series[p.series.length - 1] }))
      .sort((a, b) => (b.latest?.calc || 0) - (a.latest?.calc || 0))
      .slice(0, 200);
  }, [pages]);

  return (
    <div className="rounded-lg border border-slate-200 bg-white p-5">
      <div className="mb-1 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h3 className="text-xs font-semibold uppercase tracking-wide text-slate-500">Calculate Level</h3>
        </div>
        <div className="flex items-center gap-2">
          <span className="font-mono text-xs text-slate-500">{pages.length} сторінок · {domainsAgg.length} доменів</span>
          {pages.length > 0 && (
            <button onClick={onClear} className="text-slate-400 transition-colors hover:text-red-600" title="Очистити">
              <Trash2 className="h-4 w-4" />
            </button>
          )}
        </div>
      </div>
      <p className="mt-1 text-xs text-slate-300 leading-relaxed">💡 
        XLSX із листами «total» (кліки + calc по сторінках і місяцях) та «domains» (сумарний calc домену). Відображає динаміку видимості сайту. Кожне завантаження замінює попереднє.
      </p>
      {saveWarning && pages.length > 0 && (
        <p className="mb-1 text-xs text-amber-600">Обсяг завеликий для збереження між сесіями — після перезавантаження сторінки доведеться завантажити файл знову.</p>
      )}
      {status && <p className={`mt-1 text-xs ${status.type === "error" ? "text-red-600" : "text-emerald-600"}`}>{status.text}</p>}
      <label className="mt-3 flex cursor-pointer items-center justify-center gap-2 rounded-md border border-dashed border-slate-300 py-6 text-sm text-slate-500 transition-colors hover:border-slate-400 hover:bg-slate-50">
        {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}
        {loading ? "Розпізнаю файл…" : "Завантажити файл Calculate Level (.xlsx)"}
        <input ref={inputRef} type="file" accept=".xlsx,.xls" className="hidden" onChange={handleFile} disabled={loading} />
      </label>

      {pages.length > 0 && (
        <div className="mt-4 border-t border-slate-100 pt-3">
          <button onClick={() => setShowRows((s) => !s)} className="text-xs font-medium text-slate-500 hover:text-slate-700">
            {showRows ? "Сховати сторінки" : "Показати топ сторінок за рівнем (calc)"}
          </button>
          {showRows && (
            <div className="mt-3 max-h-64 overflow-auto rounded-md border border-slate-200">
              <table className="w-full text-xs">
                <thead className="sticky top-0 bg-slate-50 text-slate-500">
                  <tr>
                    <th className="px-2 py-1.5 text-left font-medium">Домен</th>
                    <th className="px-2 py-1.5 text-left font-medium">Сторінка</th>
                    <th className="px-2 py-1.5 text-left font-medium">Останній calc</th>
                    <th className="px-2 py-1.5 text-left font-medium">Останні кліки</th>
                    <th className="px-2 py-1.5 text-left font-medium">Періодів</th>
                  </tr>
                </thead>
                <tbody>
                  {topPages.map((p) => (
                    <tr key={p.id} className="border-t border-slate-100 hover:bg-slate-50">
                      <td className="whitespace-nowrap px-2 py-1.5 text-slate-700">{p.domain}</td>
                      <td className="max-w-[220px] truncate px-2 py-1.5 text-slate-700" title={p.page}>{p.groupName || p.page}</td>
                      <td className="px-2 py-1.5 font-mono text-slate-700">{p.latest ? p.latest.calc.toFixed(2) : "—"}</td>
                      <td className="px-2 py-1.5 font-mono text-slate-700">{p.latest ? p.latest.clicks : "—"}</td>
                      <td className="px-2 py-1.5 font-mono text-slate-500">{p.series.length}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              <p className="px-2 py-1.5 text-[11px] text-slate-400">Показано топ-{topPages.length} з {pages.length} за останнім рівнем calc.</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

