function TopicsPositionGroupRow({ group, total, withPos, inTopN, topics, threshold, advByTopic, urlByTopic, lastSnapshotDate, selectedTopics, onToggleTopic }) {
  const [open, setOpen] = useState(false);
  const isHighPriority = /group [12]/i.test(group);
  const pct = total > 0 ? Math.round((inTopN / total) * 100) : 0;
  const barColor = pct >= 50 ? "bg-emerald-500" : pct >= 20 ? "bg-amber-400" : pct > 0 ? "bg-amber-600" : "bg-slate-400";
  const dateLabel = lastSnapshotDate ? lastSnapshotDate.getDate().toString().padStart(2,"0") + "." + (lastSnapshotDate.getMonth()+1).toString().padStart(2,"0") + "." + lastSnapshotDate.getFullYear() : "";

  // Position change stats
  const withDelta = topics.filter(t => t.delta !== null && t.delta !== undefined);
  const improved = withDelta.filter(t => t.delta < 0).length;  // lower = better
  const worsened = withDelta.filter(t => t.delta > 0).length;
  const unchanged = withDelta.filter(t => t.delta === 0).length;
  const avgDelta = withDelta.length > 0 ? withDelta.reduce((s, t) => s + t.delta, 0) / withDelta.length : null;
  const hasDelta = withDelta.length > 0;
  return (
    <div className={`rounded-md border px-3 py-2 ${isHighPriority ? "border-slate-300 bg-slate-100" : "border-slate-100 bg-slate-50"}`}>
      <div className="flex items-center gap-3">
        <span className={`w-16 shrink-0 text-xs font-semibold ${isHighPriority ? "text-red-700" : "text-slate-600"}`}>{group}</span>
        <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-slate-200">
          <div className={`h-1.5 rounded-full transition-all ${barColor}`} style={{ width: `${pct}%` }} />
        </div>
        <span className="w-8 shrink-0 text-right font-mono text-[11px] text-slate-500">{pct}%</span>
        <span className="w-28 shrink-0 text-right font-mono text-[11px] text-slate-400">{inTopN}/{total} в ТОП-{threshold}</span>
        {hasDelta && (
          <div className="flex items-center gap-1.5 shrink-0 w-36 justify-end">
            {improved > 0 && <span className="flex items-center gap-0.5 font-mono text-[11px] text-emerald-600" title="Покращили позицію">▲{improved}</span>}
            {unchanged > 0 && <span className="font-mono text-[11px] text-slate-300" title="Без змін">—{unchanged}</span>}
            {worsened > 0 && <span className="flex items-center gap-0.5 font-mono text-[11px] text-red-500" title="Погіршили позицію">▼{worsened}</span>}
            {avgDelta !== null && (
              <span className={`rounded px-1.5 py-0.5 font-mono text-[10px] font-semibold ${avgDelta < 0 ? "bg-emerald-50 text-emerald-700" : avgDelta > 0 ? "bg-red-50 text-red-600" : "bg-slate-50 text-slate-400"}`}
                title={`Середня зміна позиції: ${avgDelta > 0 ? "+" : ""}${avgDelta.toFixed(1)} (від'ємне = покращення)`}>
                {avgDelta < 0 ? "▲" : avgDelta > 0 ? "▼" : "="}{Math.round(Math.abs(avgDelta))} avg
              </span>
            )}
          </div>
        )}
        <button onClick={() => setOpen((v) => !v)} className="shrink-0 text-[11px] font-medium text-slate-500 hover:text-slate-700">
          {open ? "↑" : total + " тем ↓"}
        </button>
      </div>
      {open && (
        <div className="mt-2 max-h-56 overflow-auto rounded border border-slate-200 bg-white">
          <table className="w-full text-xs">
            <thead className="sticky top-0 bg-slate-50 text-slate-500">
              <tr className="border-b border-slate-100">
                <th className="w-7 px-2 py-1.5">
                  {selectedTopics && onToggleTopic && (
                    <label className="flex items-center gap-1 cursor-pointer text-[10px] text-slate-400 hover:text-slate-600 select-none whitespace-nowrap font-normal">
                      <input
                        type="checkbox"
                        checked={topics.length > 0 && topics.every(t => selectedTopics.has(t.topic))}
                        onChange={() => {
                          const allSel = topics.every(t => selectedTopics.has(t.topic));
                          topics.forEach(t => {
                            if (allSel) { if (selectedTopics.has(t.topic)) onToggleTopic(t.topic); }
                            else { if (!selectedTopics.has(t.topic)) onToggleTopic(t.topic); }
                          });
                        }}
                        className="cursor-pointer"
                      />
                      всі
                    </label>
                  )}
                </th>
                <th className="px-2 py-1.5 text-left font-medium">Тема</th>
                <th className="w-28 px-2 py-1.5 text-left font-medium shrink-0">Домен</th>
                <th className="w-20 px-2 py-1.5 text-center font-medium shrink-0">Реклама</th>
                <th className="w-40 px-2 py-1.5 text-right font-medium shrink-0"><span className="block">Актуальна</span><span className="block">позиція ({dateLabel})</span></th>
                <th className="w-24 px-2 py-1.5 text-right font-medium whitespace-nowrap shrink-0">Зміна за період</th>
              </tr>
            </thead>
            <tbody>
              {topics.map(({ topic, pos, delta }) => {
                const hasAdv = advByTopic && advByTopic.has(topic);
                const isSel = selectedTopics && selectedTopics.has(topic);
                const url = urlByTopic && urlByTopic.get(topic);
                const domain = url ? url.replace(/^https?:\/\/(www\.)?/, "").split("/")[0] : null;
                return (
                  <tr key={topic} className={"border-t border-slate-100 hover:bg-slate-50 cursor-pointer" + (isSel ? " bg-teal-50" : "")} onClick={() => onToggleTopic && onToggleTopic(topic)}>
                    <td className="w-7 px-2 py-1.5" onClick={e => e.stopPropagation()}>
                      <input type="checkbox" checked={!!isSel} onChange={() => onToggleTopic && onToggleTopic(topic)} className="cursor-pointer" />
                    </td>
                    <td className="px-2 py-1.5 text-slate-600">
                      <div>
                        {url
                          ? <a href={asClickableUrl(url)} target="_blank" rel="noopener noreferrer" className="text-teal-700 underline decoration-teal-200 hover:text-teal-900" onClick={e => e.stopPropagation()}>{topic}</a>
                          : topic}
                        {url && <span className="font-mono text-[10px] text-slate-400 break-all"> ({normalizePageUrl(url)})</span>}
                      </div>
                    </td>
                    <td className="px-2 py-1.5 font-mono text-[10px] text-slate-500">{domain || "—"}</td>
                    <td className="px-2 py-1.5 text-center">
                      {hasAdv ? <span className="text-[11px] text-violet-700">проставлена</span> : <span className="text-slate-300">—</span>}
                    </td>
                    <td className={`px-2 py-1.5 text-right font-mono ${pos != null && pos <= threshold ? "font-semibold text-emerald-600" : "text-slate-500"}`}>
                      {pos != null ? pos.toFixed(0) : <span className="text-slate-300">—</span>}
                    </td>
                    <td className="px-2 py-1.5 text-right font-mono">
                      {delta != null ? (
                        <span className={delta < 0 ? "text-emerald-600" : delta > 0 ? "text-red-500" : "text-slate-400"}>
                          {delta < 0 ? "▲" : delta > 0 ? "▼" : "="}{Math.abs(delta).toFixed(0)}
                        </span>
                      ) : <span className="text-slate-300">—</span>}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

/* =========================================================
   Custom date picker — DD/MM/YYYY, week starts Monday
========================================================= */
function DatePickerInput({ value, onChange }) {
  const [open, setOpen] = useState(false);
  const ref = React.useRef(null);
  const today = new Date();
  const parsed = value ? new Date(value + "T00:00:00") : null;
  const [view, setView] = useState(parsed || today);

  useEffect(() => {
    function handleClick(e) { if (ref.current && !ref.current.contains(e.target)) setOpen(false); }
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, []);

  const y = view.getFullYear();
  const m = view.getMonth();
  const MONTHS = ["Січень","Лютий","Березень","Квітень","Травень","Червень","Липень","Серпень","Вересень","Жовтень","Листопад","Грудень"];
  const DAYS = ["Пн","Вт","Ср","Чт","Пт","Сб","Нд"];

  // Monday-first: (getDay()+6)%7 → 0=Mon…6=Sun
  const firstDow = (new Date(y, m, 1).getDay() + 6) % 7;
  const totalDays = new Date(y, m + 1, 0).getDate();
  const cells = [];
  for (let i = 0; i < firstDow; i++) cells.push(null);
  for (let d = 1; d <= totalDays; d++) cells.push(d);

  const toStr = (yr, mo, d) => `${yr}-${String(mo+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`;
  const display = parsed ? `${String(parsed.getDate()).padStart(2,"0")}.${String(parsed.getMonth()+1).padStart(2,"0")}.${parsed.getFullYear()}` : "";

  return (
    <div ref={ref} className="relative">
      <input
        readOnly
        value={display}
        placeholder="дд.мм.рррр"
        onClick={() => { setView(parsed || today); setOpen((v) => !v); }}
        className="w-32 cursor-pointer rounded-md border border-slate-300 px-2 py-1.5 font-mono text-sm text-slate-700 caret-transparent"
      />
      {open && (
        <div className="absolute left-0 top-full z-50 mt-1 w-60 rounded-lg border border-slate-200 bg-white p-3 shadow-lg">
          <div className="mb-2 flex items-center justify-between">
            <button onClick={() => setView(new Date(y, m - 1, 1))} className="px-1 text-slate-500 hover:text-slate-900">‹</button>
            <span className="text-xs font-semibold text-slate-700">{MONTHS[m]} {y}</span>
            <button onClick={() => setView(new Date(y, m + 1, 1))} className="px-1 text-slate-500 hover:text-slate-900">›</button>
          </div>
          <div className="grid grid-cols-7 text-center">
            {DAYS.map((d) => <div key={d} className="py-0.5 text-[10px] text-slate-400">{d}</div>)}
            {cells.map((d, i) => {
              const isSelected = d && value === toStr(y, m, d);
              const isToday = d && toStr(y, m, d) === toStr(today.getFullYear(), today.getMonth(), today.getDate());
              return (
                <div key={i} onClick={d ? () => { onChange(toStr(y, m, d)); setOpen(false); } : undefined}
                  className={`rounded py-0.5 text-xs ${d ? "cursor-pointer" : ""} ${isSelected ? "bg-teal-500 text-white" : isToday ? "font-bold text-teal-700" : d ? "text-slate-700 hover:bg-slate-100" : ""}`}>
                  {d || ""}
                </div>
              );
            })}
          </div>
          <div className="mt-2 flex justify-between border-t border-slate-100 pt-2">
            {value ? <button onClick={() => { onChange(""); setOpen(false); }} className="text-[11px] text-slate-400 hover:text-slate-600">Скинути</button> : <span />}
            <button onClick={() => { onChange(toStr(today.getFullYear(), today.getMonth(), today.getDate())); setOpen(false); }} className="text-[11px] font-medium text-teal-700 hover:text-teal-900">Сьогодні</button>
          </div>
        </div>
      )}
    </div>
  );
}

/* =========================================================
   Inline alert block — compact version for timeline tabs
========================================================= */

const INLINE_ALERT_TONES = {
  danger: { border: "border-red-200", bg: "bg-red-50", iconBg: "bg-red-100", iconText: "text-red-600", title: "text-red-900", link: "text-red-700 decoration-red-300" },
  warning: { border: "border-amber-200", bg: "bg-amber-50", iconBg: "bg-amber-100", iconText: "text-amber-600", title: "text-amber-900", link: "text-amber-700 decoration-amber-300" },
};

function InlineAlertBlock({ tone, icon: Icon, title, items }) {
  const [expanded, setExpanded] = useState(false);
  const t = INLINE_ALERT_TONES[tone] || INLINE_ALERT_TONES.warning;
  const shown = expanded ? items : items.slice(0, 3);
  return (
    <div className={`rounded-lg border ${t.border} ${t.bg} px-4 py-3`}>
      <div className="flex items-center gap-2">
        <span className={`inline-flex h-6 w-6 shrink-0 items-center justify-center rounded ${t.iconBg}`}>
          <Icon className={`h-3.5 w-3.5 ${t.iconText}`} />
        </span>
        <span className={`text-xs font-semibold ${t.title}`}>{title}</span>
      </div>
      <ul className="mt-2 space-y-1 pl-8">
        {shown.map((it) => (
          <li key={it.key} className="text-xs text-slate-700">
            {it.url
              ? <a href={it.url} target="_blank" rel="noopener noreferrer" className={`font-medium underline ${t.link} hover:opacity-80`}>{it.label}</a>
              : <span className="font-medium">{it.label}</span>
            }
            {it.meta && <span className="ml-1 text-slate-500">{it.meta}</span>}
          </li>
        ))}
      </ul>
      {items.length > 3 && (
        <button onClick={() => setExpanded(v => !v)} className={`mt-1.5 pl-8 text-xs font-medium ${t.iconText} hover:opacity-80`}>
          {expanded ? "Згорнути" : `Показати ще ${items.length - 3}`}
        </button>
      )}
    </div>
  );
}

/* =========================================================
   Donor coverage block — tabbed by type
========================================================= */

function UnusedDonorsList({ unused, linkbuilders = [], donorType, selectedDomain, addOrder, activeOrders = [], allAuthors = [] }) {
  const [selected, setSelected] = useState(new Set());
  const [showModal, setShowModal] = useState(false);
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [assignee, setAssignee] = useState("");
  const [comment, setComment] = useState("");
  const toggle = (id) => setSelected((s) => { const n = new Set(s); n.has(id) ? n.delete(id) : n.add(id); return n; });
  const toggleAll = () => setSelected(selected.size === unused.length ? new Set() : new Set(unused.map((d) => d.id)));

  function handleCreate() {
    if (!assignee) return;
    const selectedDonors = unused.filter(d => selected.has(d.id));
    selectedDonors.forEach(d => {
      addOrder({
        type: "link",
        domain: selectedDomain || d.domain || "",
        donorType: donorType || "",
        donorUrl: d.domain,
        author: assignee,
        managedBy: "Менеджер",
        planDate: dateTo ? new Date(dateTo) : (dateFrom ? new Date(dateFrom) : null),
        history: [
          { role: "manager", name: "Менеджер", text: `Тип: ${donorType || "—"}. Донор: ${d.domain}.${comment ? " " + comment : ""}`, date: new Date() },
        ],
      });
    });
    setShowModal(false);
    setSelected(new Set());
    setComment("");
    setAssignee("");
  }

  const allLinkbuilderNames = [...new Set(linkbuilders.map(l => l.author))];

  return (
    <>
      <div className="mb-2 flex items-center justify-between gap-2">
        <p className="text-xs font-semibold text-amber-700">Не використані — {unused.length}</p>
        <button
          onClick={() => setShowModal(true)}
          className="flex items-center gap-1.5 rounded-md bg-teal-50 px-2.5 py-1 text-xs font-medium text-teal-700 border border-teal-200 hover:bg-teal-100"
        >
          📋 Запланувати вибрані донори в роботу{selected.size > 0 ? " (" + selected.size + ")" : ""}
        </button>
      </div>
      <div className="max-h-52 overflow-auto rounded-md border border-amber-100 bg-amber-50">
        <table className="w-full text-xs">
          <thead className="sticky top-0 bg-amber-100">
            <tr className="border-b border-amber-200">
              <th className="w-8 px-2 py-1.5 text-left">
                <input type="checkbox" checked={selected.size === unused.length && unused.length > 0} onChange={toggleAll} className="cursor-pointer" />
              </th>
              <th className="px-2 py-1.5 text-left font-medium text-amber-800">Домен донора</th>
            </tr>
          </thead>
          <tbody>
            {unused.map((d) => {
              const inProgress = activeOrders.find(o =>
                o.type === "link" &&
                o.donorUrl === d.domain &&
                o.status !== "accepted"
              );
              const accepted = !inProgress && activeOrders.find(o =>
                o.type === "link" &&
                o.donorUrl === d.domain &&
                o.status === "accepted"
              );
              return (
                <tr key={d.id} className={`border-t border-amber-100 first:border-0 ${inProgress ? "opacity-60" : "hover:bg-amber-100/50 cursor-pointer"}`}
                  onClick={() => !inProgress && toggle(d.id)}>
                  <td className="w-8 px-2 py-1.5">
                    <input type="checkbox" checked={selected.has(d.id)} disabled={!!inProgress}
                      onChange={() => toggle(d.id)} onClick={(e) => e.stopPropagation()} className="cursor-pointer disabled:cursor-not-allowed" />
                  </td>
                  <td className="px-2 py-1.5 font-mono text-slate-700">
                    {d.domain}
                    {inProgress && (
                      <span className="ml-2 rounded bg-amber-200 px-1.5 py-0.5 text-[10px] font-medium text-amber-800">
                        in progress · {inProgress.author || "—"}
                      </span>
                    )}
                    {accepted && (
                      <span className="ml-2 rounded bg-emerald-100 px-1.5 py-0.5 text-[10px] font-medium text-emerald-700">
                        ✅ виконано в сесії · запиши результат у файл
                      </span>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30" onClick={() => setShowModal(false)}>
          <div className="relative w-full max-w-2xl rounded-xl border border-slate-200 bg-white p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}>
            <button onClick={() => setShowModal(false)} className="absolute right-4 top-4 text-slate-400 hover:text-slate-600 text-lg">✕</button>
            <h3 className="mb-1 font-display text-base font-semibold text-slate-900">Запланувати донорів в роботу</h3>
            <p className="mb-4 text-xs text-slate-400">{selected.size > 0 ? "Вибрано " + selected.size + " донорів · тип: " + (donorType || "—") : "Оберіть донорів у списку"}</p>

            {/* Linkbuilder selector */}
            <div className="mb-4">
              <div className="mb-2 text-xs font-medium text-slate-600">Призначити лінкбілдеру <span className="text-red-400">*</span></div>
              <div className="flex flex-wrap gap-2">
                {allLinkbuilderNames.length > 0 ? allLinkbuilderNames.map(name => (
                  <button key={name} onClick={() => setAssignee(name)}
                    className={`rounded-md px-3 py-1.5 text-xs font-medium transition-colors ${assignee === name ? "bg-slate-700 text-white" : "bg-slate-100 text-slate-600 hover:bg-slate-200"}`}>
                    {name}
                    {linkbuilders.find(l => l.author === name) && (
                      <span className="ml-1.5 opacity-60">{linkbuilders.find(l => l.author === name).total} in progress</span>
                    )}
                  </button>
                )) : (
                  <input value={assignee} onChange={e => setAssignee(e.target.value)} placeholder="Ім'я лінкбілдера..."
                    className="rounded-md border border-slate-200 px-3 py-1.5 text-xs focus:border-teal-400 focus:outline-none" />
                )}
              </div>
            </div>

            {/* Date range */}
            <div className="mb-4">
              <div className="mb-2 text-xs font-medium text-slate-600">Проміжок дат для планування</div>
              <div className="flex items-center gap-2">
                <DatePickerInput value={dateFrom} onChange={setDateFrom} />
                <span className="text-slate-400 text-xs">—</span>
                <DatePickerInput value={dateTo} onChange={setDateTo} />
              </div>
            </div>

            {/* Optional comment */}
            <div className="mb-5">
              <div className="mb-2 text-xs font-medium text-slate-600">Коментар (необов'язково)</div>
              <textarea value={comment} onChange={e => setComment(e.target.value)} rows={2}
                placeholder="Додаткові інструкції для виконавця..."
                className="w-full rounded-md border border-slate-200 px-3 py-2 text-xs text-slate-700 placeholder-slate-300 focus:border-teal-400 focus:outline-none resize-none" />
            </div>

            <button
              onClick={handleCreate}
              disabled={selected.size === 0 || !assignee}
              className={`w-full rounded-lg px-4 py-2.5 text-sm font-semibold text-white transition-colors ${selected.size > 0 && assignee ? "bg-teal-600 hover:bg-teal-700" : "bg-teal-500 opacity-40 cursor-not-allowed"}`}>
              Створити замовлення ({selected.size} донорів)
            </button>
          </div>
        </div>
      )}
    </>
  );
}

