  pending:   { label: "Очікує підтвердження", bg: "bg-blue-50",     text: "text-blue-700",    dot: "bg-blue-400"    },
  revision:  { label: "На доопрацювання",     bg: "bg-amber-50",    text: "text-amber-700",   dot: "bg-amber-400"   },
  confirmed: { label: "В роботу",             bg: "bg-teal-50",     text: "text-teal-700",    dot: "bg-teal-500"    },
  done:      { label: "Виконано",             bg: "bg-violet-50",   text: "text-violet-700",  dot: "bg-violet-500"  },
